interface MainWindowProps {
    auth: UseGithubAuthResult
    initialProjectOpenResolution: ProjectOpenResolution | null
    toolbarAction: ReactNode
}

/** Main window: owns the global layout and switches between desktop and mobile presentations. */
export function MainWindow(props: MainWindowProps) {
    const { auth, initialProjectOpenResolution, toolbarAction } = props
    const location = useAppLocation()
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const [isMenuOpen, setIsMenuOpen] = useState(false)
    const project = useProjectReference()
    const isConfigOpen = location.pathname === '/config'
    const regexpAgent = useMemo(
        () => isSearchRegexpAgentAvailable() ? createSearchRegexpAgent() : undefined,
        [],
    )

    useEffect(() => keyboardShortcutService.register(GLOBAL_SEARCH_SHORTCUT_BINDING), [])

    const handleOpenMenu = useCallback(() => {
        setIsMenuOpen(true)
    }, [])

    const handleCloseMenu = useCallback(() => {
        setIsMenuOpen(false)
    }, [])

    const handleOpenConfig = useCallback(() => {
        navigateTo('/config')
    }, [])

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
            <AppMenu
                accessToken={auth.accessToken}
                auth={auth}
                extraActions={toolbarAction}
                initialProjectOpenResolution={initialProjectOpenResolution}
                isGithubAuthenticated={auth.isAuthenticated}
                isMobile={isMobile}
                onOpenConfig={handleOpenConfig}
                onOpenMobileMenu={handleOpenMenu}
                search={<SearchControl isMobile={isMobile} regexpAgent={regexpAgent} />}
            />
            <ProjectWorkspace
                auth={auth}
                isMenuOpen={isMenuOpen}
                key={project ? `${project.id}:${project.branch}` : 'no-project'}
                onLeftPanelInteraction={handleCloseMenu}
            />
            {!isMobile ? <StatusBar /> : null}
            {isConfigOpen ? <ConfigPage hash={location.hash} /> : null}
        </Box>
    )
}

import { Box } from '@mui/material'
import { useEffect, useMemo, useRef } from 'react'
import { projectStatsService } from '../../services/stats/project_stats_service'
import type { StatsCardDescriptor } from '../../services/stats/project_stats_types'
import { useProjectState } from '../hooks/use_project_state'
import { useWorkspaceView } from '../hooks/use_workspace_view'
import { StatsContent } from './stats_content'

/** Lifetime-stable stats surface; repository reads begin only when stats mode becomes visible. */
export function StatsView() {
    const { project, snapshot } = useProjectState()
    const { viewMode } = useWorkspaceView()
    const cards = useMemo(() => {
        const projectCards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

        return projectCards.flatMap((card): StatsCardDescriptor[] => card.header.internalId ? [{
            internalId: card.header.internalId,
            path: card.path,
            title: card.header.title,
            visibleId: card.header.id,
        }] : [])
    }, [snapshot])
    const cardsRef = useRef(cards)

    useEffect(() => {
        cardsRef.current = cards
    }, [cards])

    useEffect(() => {
        if (viewMode !== 'stats' || !project) return

        void projectStatsService.open(cardsRef.current)

        return () => projectStatsService.close()
    }, [project, viewMode])

    return (
        <Box
            aria-label="Stats view"
            sx={{ bgcolor: 'background.default', display: viewMode === 'stats' ? 'flex' : 'none', flex: 1, minHeight: 0, overflow: 'hidden' }}
        >
            <StatsContent />
        </Box>
    )
}

