import type { ActionRunResult } from '../../../../data/action_run_types'
import type { PopupRunStatus } from '../popup/action_popup_defaults'

interface ActionRunResultSnapshot {
    result: ActionRunResult | null
    runId: string | null
    status: PopupRunStatus
}

type Listener = () => void

const INITIAL_SNAPSHOT: ActionRunResultSnapshot = { result: null, runId: null, status: 'idle' }

/** Owns transient start failures and injected-run results outside popup roots. */
export class ActionRunResultStore {
    private readonly listeners = new Set<Listener>()
    private snapshot = INITIAL_SNAPSHOT

    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: Listener) => {
        this.listeners.add(listener)

        return () => this.listeners.delete(listener)
    }

    setRunning() {
        this.publish({ result: null, runId: null, status: 'running' })
    }

    setRunId(runId: string) {
        this.publish({ ...this.snapshot, runId })
    }

    setResult(result: ActionRunResult) {
        this.publish({ result, runId: null, status: result.status })
    }

    private publish(snapshot: ActionRunResultSnapshot) {
        this.snapshot = snapshot
        for (const listener of this.listeners) listener()
    }
}

import { IconButton, ListItemIcon, MenuItem, Stack, Tooltip } from '@mui/material'
import { useEffect, useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { displayActionsForContext, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { dialogService } from '../../../../services/dialog_service'
import { useActions } from '../../../hooks/use_actions'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { ActionIcon } from './action_icon'
import { resolveActionIcon, type ActionIconSource } from './action_icon_resolver'
import { ActionPopup } from '../popup/action_popup'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'

/** How action entry points are rendered in an existing toolbar or menu. */
export type ActionEntryVariant = 'icons' | 'menuItems'
export type ActionEntryVisibility = 'all-matching' | 'explicit-context'

interface ActionEntryPointsProps {
    context: ActionContext
    onMenuItemSelected?: () => void
    popupAnchorElement?: HTMLElement | null
    variant: ActionEntryVariant
    visibility?: ActionEntryVisibility
}

const DEFAULT_ICON_SOURCE: ActionIconSource = { dataUri: null }

interface ActionPopupState {
    actionId: string
    anchorElement: HTMLElement
}

/**
 * Context-sensitive action entry points shown close to a card/file/folder. Filters
 * the loaded actions by `appliesTo`, and on activation opens a resizable popup bound
 * to the action and context. `before`/`after` shortcuts push a new popup for the
 * related action with the same context.
 */
export function ActionEntryPoints(props: ActionEntryPointsProps) {
    const { context, onMenuItemSelected, popupAnchorElement, variant, visibility = 'all-matching' } = props
    const { actions: loadedActions } = useActions()
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const runDisabled = readOnly || !!runningRun
    const [iconSources, setIconSources] = useState<Record<string, ActionIconSource>>({})
    const [popupState, setPopupState] = useState<ActionPopupState | null>(null)

    const matching = useMemo(() => {
        const contextActions = displayActionsForContext(loadedActions, context)
        if (visibility === 'explicit-context') {
            return contextActions.filter((action) => action.appliesTo?.kind === context.kind)
        }

        return contextActions
    }, [context, loadedActions, visibility])

    useEffect(() => {
        let isActive = true

        const loadIcons = async () => {
            const entries = await Promise.all(matching.map(async (action) => [action.id, await resolveActionIcon(action.icon)] as const))
            if (!isActive) return

            setIconSources(Object.fromEntries(entries))
        }

        void loadIcons()

        return () => {
            isActive = false
        }
    }, [matching])

    if (matching.length === 0) return null

    const open = (actionId: string, anchorElement: HTMLElement) => {
        onMenuItemSelected?.()
        setPopupState({ actionId, anchorElement })
    }

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        try {
            const { actionId } = event.currentTarget.dataset
            if (!actionId) throw new Error('Missing action id on action entry point')

            open(actionId, popupAnchorElement ?? event.currentTarget)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action popup could not be opened' })
        }
    }

    const iconSourceFor = (action: ActionDefinition) => iconSources[action.id] ?? DEFAULT_ICON_SOURCE

    const closePopup = () => {
        setPopupState(null)
    }

    const popup = popupState ? (
        <ActionPopup
            anchorElement={popupState.anchorElement}
            context={context}
            draggable
            initialActionId={popupState.actionId}
            key={popupState.actionId}
            onClose={closePopup}
        />
    ) : null

    const menuItems = (
        <>
            {matching.map((action) => (
                <MenuItem
                    data-action-id={action.id}
                    disabled={runDisabled}
                    key={action.id}
                    onClick={handleOpen}
                >
                    <ListItemIcon>
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </ListItemIcon>
                    {action.label}
                </MenuItem>
            ))}
            {popup}
        </>
    )

    if (variant === 'menuItems') return menuItems

    return (
        <Stack direction="row" spacing={0.25} sx={{ flexShrink: 0 }}>
            {matching.map((action) => (
                <Tooltip key={action.id} title={action.label}>
                    <IconButton
                        aria-label={action.label}
                        data-action-id={action.id}
                        disabled={runDisabled}
                        onClick={handleOpen}
                        size="small"
                    >
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </IconButton>
                </Tooltip>
            ))}
            {popup}
        </Stack>
    )
}

import { Fab, Tooltip } from '@mui/material'
import RobotOutline from 'mdi-material-ui/RobotOutline'
import { useRef, useState } from 'react'
import type { MouseEvent, PointerEvent as ReactPointerEvent } from 'react'
import { projectContext } from '../../data/action_context'
import { ActionPopup } from '../actions/run/popup/action_popup'

const FAB_MARGIN = 16
const FAB_SIZE = 56
const DRAG_THRESHOLD = 5
const PROJECT_CONTEXT = projectContext()

interface FabPosition {
    left: number
    top: number
}

interface DragState extends FabPosition {
    dragged: boolean
    pointerId: number
    startX: number
    startY: number
}

function initialPosition(): FabPosition {
    return {
        left: Math.max(FAB_MARGIN, window.innerWidth - FAB_SIZE - FAB_MARGIN),
        top: Math.max(FAB_MARGIN, window.innerHeight - FAB_SIZE - FAB_MARGIN),
    }
}

function clampPosition(left: number, top: number): FabPosition {
    return {
        left: Math.min(Math.max(left, FAB_MARGIN), Math.max(FAB_MARGIN, window.innerWidth - FAB_SIZE - FAB_MARGIN)),
        top: Math.min(Math.max(top, FAB_MARGIN), Math.max(FAB_MARGIN, window.innerHeight - FAB_SIZE - FAB_MARGIN)),
    }
}

/** Project-wide free-form agent launcher, movable anywhere in application viewport. */
export function AgentChatFab() {
    const [position, setPosition] = useState(initialPosition)
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const dragRef = useRef<DragState | null>(null)

    const handlePointerDown = (event: ReactPointerEvent<HTMLButtonElement>) => {
        dragRef.current = {
            ...position,
            dragged: false,
            pointerId: event.pointerId,
            startX: event.clientX,
            startY: event.clientY,
        }
        event.currentTarget.setPointerCapture?.(event.pointerId)
    }

    const handlePointerMove = (event: ReactPointerEvent<HTMLButtonElement>) => {
        const drag = dragRef.current
        if (!drag || drag.pointerId !== event.pointerId) return

        const deltaX = event.clientX - drag.startX
        const deltaY = event.clientY - drag.startY
        if (!drag.dragged && Math.hypot(deltaX, deltaY) < DRAG_THRESHOLD) return

        drag.dragged = true
        setAnchorElement(null)
        setPosition(clampPosition(drag.left + deltaX, drag.top + deltaY))
    }

    const handlePointerUp = (event: ReactPointerEvent<HTMLButtonElement>) => {
        if (dragRef.current?.pointerId !== event.pointerId) return

        event.currentTarget.releasePointerCapture?.(event.pointerId)
    }

    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
        if (dragRef.current?.dragged) {
            event.preventDefault()
            dragRef.current = null
            return
        }

        dragRef.current = null
        const nextAnchorElement = event.currentTarget
        setAnchorElement((current) => current ? null : nextAnchorElement)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    return (
        <>
            <Tooltip title="Project agent">
                <Fab
                    aria-label="Project agent"
                    color="primary"
                    onClick={handleClick}
                    onPointerDown={handlePointerDown}
                    onPointerMove={handlePointerMove}
                    onPointerUp={handlePointerUp}
                    sx={{ left: position.left, position: 'fixed', top: position.top, touchAction: 'none', zIndex: 'appBar' }}
                >
                    <RobotOutline />
                </Fab>
            </Tooltip>
            {anchorElement ? (
                <ActionPopup
                    anchorElement={anchorElement}
                    context={PROJECT_CONTEXT}
                    draggable
                    onClose={handleClose}
                />
            ) : null}
        </>
    )
}

